fn get_min_val(a: &Vec<i8>) -> i8 {
    *a.iter().min().unwrap()
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    *a.iter().max().unwrap()
}

fn nanquantile(a: Vec<i8>, q: i8) -> i8 {
    // Handle edge cases first
    if q <= 0 {
        return get_min_val(&a);
    }
    if q >= 100 {
        return get_max_val(&a);
    }
    
    // Sort the array
    let mut sorted = a.clone();
    sorted.sort();
    
    // Calculate the index for the quantile
    // Using linear interpolation between quantiles
    let n = sorted.len() as f64;
    let q_fraction = q as f64 / 100.0;
    
    // Calculate the position in the sorted array
    let pos = q_fraction * (n - 1.0);
    
    // Get the lower and upper indices
    let lower_idx = pos.floor() as usize;
    let upper_idx = pos.ceil() as usize;
    
    if lower_idx == upper_idx {
        // Exact index
        sorted[lower_idx]
    } else {
        // Linear interpolation between two values
        let lower_val = sorted[lower_idx] as f64;
        let upper_val = sorted[upper_idx] as f64;
        let weight = pos - lower_idx as f64;
        
        let interpolated = lower_val + (upper_val - lower_val) * weight;
        interpolated.round() as i8
    }
}